import axios from 'axios';

// ENDPOINTS
const API_APPOINTMENT = 'http://localhost:4007/appointments';
const API_CANCEL = 'http://localhost:4008/cancel';

// FUNCIONES PARA EL LOGIN
export async function loginUser(username, password) {
    const response = await fetch('http://localhost:8080/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Login failed: ${errorText}`);
    }

    const data = await response.json();
    if (data.token) {
        localStorage.setItem('token', data.token);
    }
    return data;
}

// FUNCIONES PARA EL DASHBOARD
export async function getAppointments() {
    const res = await axios.get(API_APPOINTMENT, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
    });
    return res.data;
}

export async function createAppointment(data) {
    const res = await axios.post(API_APPOINTMENT, data, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
    });
    return res.data;
}

export async function cancelAppointment(id) {
    const res = await axios.delete(`${API_CANCEL}/${id}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
    });
    return res.data;
}
